//! The PowerVR BXS-4-64 backend. Not in a `gpu-vivante` build: that one has
//! `vivante/` instead, and the shader ABI it compiles against is the GC7000's.
#![cfg(feature = "gpu-powervr")]

pub mod backend;
/// The programs this backend binds itself (the frame and clear quads' shaders,
/// the background object's clear-attach programs), made by our own compiler:
/// generated by `yakogl-precompile --internal` from the list's `internal
/// powervr` lines.
pub mod internal;
/// Mesa's programs for the same jobs (pco_shc, captured), which the host tests
/// run ours against (tests/internal_programs.rs): reference material, in no
/// product image.
#[cfg(mesa_reference)]
#[path = "../../tests/reference/pvr_internal.rs"]
pub mod mesa_internal;
/// Mesa's csbgen packers (bindgen output, `yakogl-tools csbgen-bindings`;
/// build.rs compiles the C wrappers they link to).
